cases.raw:
{
  "summary": "정상적인 임대차 계약은 등기부등본 확인과 서류 검토에 시간이 필요합니다. '오늘 안 하면 다른 사람이 계약한다'는 말은 검증 시간을 빼앗기 위한 사기 수법입니다.",
  "points": [
    {
      "id": "pay-urgency",
      "why": "정상적인 임대차 계약은 등기부등본 확인과 서류 검토에 시간이 필요합니다."
    }
  ],
  "ask": [
    "다음으로, 어떤 금액도 입금하지 마십시오."
  ]
}

{
  "summary": "A lease gives time to check the property register and documents. Rely on the listing to avoid being pressured to pay immediately.",
  "points": [
    {
      "id": "pay-urgency",
      "why": "A legitimate lease gives you time to check the property register and documents. 'Someone else will take it today' is the most common tactic used to stop you from verifying anything."
    }
  ],
  "ask": [
    "What is the most common reason someone might stop you from verifying the property register?"
  ]
}

{
  "summary": "소유자 명의 계좌로 송금을 요청하는 것이 보증금의 정확성을 보장하는 것이 필요합니다.",
  "points": [
    {
      "id": "pay-personal-account",
      "why": "보증금은 반드시 등기부등본상 소유자 본인 명의 계좌로 입금해야 합니다."
    }
  ],
  "ask": [
    "보증금의 소유자 이름과 입금 계좌 예금주가 글자 하나까지 같은지 확인하세요."
  ]
}

{
  "summary": "Check that the account holder name matches the registered owner exactly.",
  "points": [
    {
      "id": "pay-personal-account",
      "why": "The deposit must go to an account in the registered owner's own name."
    }
  ],
  "ask": [
    "What is the registered owner's name and the account holder's name?"
  ]
}

{
  "summary": "현금 요구 / 영수증·계약서 미발행",
  "points": [
    {
      "id": "pay-cash-no-receipt",
      "why": "현금 거래는 증거가 남지 않습니다. 계약서와 영수증 없이 지급한 돈은 법적으로 입증하기 어렵습니다."
    }
  ],
  "ask": [
    "이체 방법과 기재 내용을 확인해 보세요."
  ]
}

{
  "summary": "A rental warning finding that needs review.",
  "points": [
    {
      "id": "pay-cash-no-receipt",
      "why": "Cash leaves no trace. Money paid without a contract or receipt is very hard to prove in court."
    }
  ],
  "ask": [
    "What is the best way to prove the payment of rent?"
  ]
}

{
  "summary": "대리인 계약에서 위임장과 대리인 신분증이 미확인되면 무권대리로 무효될 수 있습니다.",
  "points": [
    {
      "id": "id-proxy-no-poa",
      "why": "소유자가 아닌 사람이 계약하려면 인감증명서와 위임장이 반드시 필요합니다."
    }
  ],
  "ask": [
    "소유자와 직접 통화(영상통화)로 확인하는 방법을 설명해주세요."
  ]
}

{
  "summary": "Proxy signing without a power of attorney is invalid; demand original power of attorney, seal certificate, and proxy ID.",
  "points": [
    {
      "id": "id-proxy-no-poa",
      "why": "Proxy signing without a power of attorney is invalid; demand original power of attorney, a seal certificate issued within 3 months, and the proxy's ID."
    }
  ],
  "ask": [
    "What is the required power of attorney and seal certificate for the proxy signing?"
  ]
}

{
  "summary": "등기부등본을 직접 발급하는 것이 필요합니다.",
  "points": [
    {
      "id": "id-refuse-register",
      "why": "등기부등본은 누구나 700원으로 직접 발급할 수 있는 공개 문서입니다. 보여주기를 거부하는 것은 숨길 것이 있다는 뜻입니다."
    }
  ],
  "ask": [
    "등기부등본을 직접 발급하는 것이 필요합니다."
  ]
}

{
  "summary": "Refusing to show the property register or documents is a reason for review.",
  "points": [
    {
      "id": "id-refuse-register",
      "why": "The property register is a public document anyone can issue for about 700 won. Refusing to show it means there is something to hide."
    }
  ],
  "ask": [
    "What is the reason for refusing to show the property register?"
  ]
}

{
  "summary": "중개사 자격 미확인",
  "points": [
    {
      "id": "id-agent-unregistered",
      "why": "무등록 중개는 불법이며, 사고가 나도 공제(보증)를 받을 수 없습니다."
    }
  ],
  "ask": [
    "중개사 자격 확인 여부 확인"
  ]
}

{
  "summary": "Unlicensed brokerage is illegal and leaves you with no insurance coverage. Look up the agency's registration number and get a copy of their indemnity certificate.",
  "points": [
    {
      "id": "id-agent-unregistered",
      "why": "Unlicensed brokerage is illegal and leaves you with no insurance coverage."
    }
  ],
  "ask": [
    "What is the agency's registration number?"
  ]
}

{
  "summary": "Check the existing finding to ensure the mortgage is properly reviewed.",
  "points": [
    {
      "id": "reg-heavy-mortgage",
      "why": "Ensure the mortgage is properly reviewed to avoid potential issues with the loan."
    }
  ],
  "ask": [
    "What is the current status of the mortgage?"
  ]
}

{
  "summary": "Check the lien amount and deposit against the property's market value to ensure your deposit is not over 70%.",
  "points": [
    {
      "id": "reg-heavy-mortgage",
      "why": "If the property is auctioned, the mortgage is repaid first, and your deposit is at risk if it exceeds 70% of the market value."
    }
  ],
  "ask": [
    "What is the lien amount and your deposit on the property?"
  ]
}

{
  "summary": "신탁등기된 부동산은 신탁회사의 소유이며, 법적 소유자가 없으며, 계약을 무효화할 수 있습니다.",
  "points": [
    {
      "id": "reg-trust",
      "why": "신탁회사의 서면 동의서를 반드시 받으세요."
    }
  ],
  "ask": [
    "신탁회사의 서면 동의서를 반드시 받으세요."
  ]
}

{
  "summary": "short explanation",
  "points": [
    {
      "id": "reg-trust",
      "why": "needs checking"
    }
  ],
  "ask": [
    "What is the trust deed and who holds the leasing authority?"
  ]
}

{
  "summary": "가압류·압류·경매 기재된 부동산은 언제든 강제 매각될 수 있으며, 후순위 임차인은 보증금을 받지 못할 수 있습니다.",
  "points": [
    {
      "id": "reg-seizure-auction",
      "why": "가압류·압류·경매개시결정이 기재된 부동산은 언제든 강제 매각될 수 있습니다."
    }
  ],
  "ask": [
    "이 기재된 부동산의 매각 가능성에 대해 어떻게 평가하시나요?"
  ]
}

{
  "summary": "A property with a seizure or auction notice can be force-sold at any time, and a junior tenant recovers almost nothing. Stop the process immediately. No explanation removes this risk.",
  "points": [
    {
      "id": "reg-seizure-auction",
      "why": "A property with a seizure or auction notice can be force-sold at any time, and a junior tenant recovers almost nothing."
    }
  ],
  "ask": [
    "What is the current status of the property?"
  ]
}

{
  "summary": "상대방이 등기·권리관계 질문을 금액이나 서류로 답하지 않고 \"별거 아니다\", \"신경 쓰지 마라\"로 넘어가고 있습니다.",
  "points": [
    {
      "id": "reg-dismiss-question",
      "why": "상대방이 금액이나 서류로 답하지 않고 질문을 넘어가고 있습니다."
    }
  ],
  "ask": [
    "\"을구에 적힌 채권최고액이 정확히 얼마인가요?"
  ]
}

{
  "summary": "The fixed assessment is 'needs_review', and the explanation is: 'They answered a question about liens, seizures or prior claims with reassurance instead of a number or a document. Those amounts are printed on the property register and take a minute to check, so steering you away from checking is itself the signal.'",
  "points": [
    {
      "id": "reg-dismiss-question",
      "why": "They answered a question about liens, seizures or prior claims with reassurance instead of a number or a document."
    }
  ],
  "ask": [
    "Ask again for the number: \"what exactly is the maximum claim amount in section 을구?\""
  ]
}
